/* Full-screen shell. Routes every action back into the existing investigation. */
(function(){
'use strict';
const UI=GameUI,$=id=>document.getElementById(id);
const icons={field:'<path d="M4 9V4h5m6 0h5v5m0 6v5h-5M9 20H4v-5"/><circle cx="12" cy="12" r="3"/>',board:'<path d="M4 4h6v5H4zm10 11h6v5h-6zM14 4h6v5h-6zM4 15h6v5H4zM7 9v6m10-6v6M10 6h4m-4 12h4"/>',notes:'<path d="M5 3h14v18H5zM8 7h8M8 11h8m-8 4h5"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zM9 3v16m6-14v16"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m0-17a3 3 0 0 1 0 6m3 4a6 6 0 0 1 3 5v2"/>',briefing:'<path d="M4 6h16v15H4zm4 0V3h8v3M4 11h16m-10-1h4v4h-4z"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3v3m-1 2h.01"/>'};
const svg=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.field}</svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=svg(el.dataset.icon));
let lastPlace=null,slateTimer,helpTab='controls';
const roomIds=Object.keys(UI.locations);
function restoreHud(){document.body.classList.remove('hud-hidden');$('restore-hud').hidden=true;}
function cleanFrame(){if(UI.getState().view!=='field')UI.view('field');if(UI.getState().ending)return;const hidden=document.body.classList.toggle('hud-hidden');$('restore-hud').hidden=!hidden;if(hidden)$('restore-hud').focus();else if(!Cinema.focus())document.querySelector('[data-view="field"]').focus();}
function update(){const s=UI.getState(),field=s.view==='field'&&!s.ending;document.body.dataset.tool=s.view;document.body.classList.toggle('tool-open',!field);document.body.classList.toggle('case-closed',!!s.ending);$('hud-lead').textContent=$('lead').textContent;$('hud-news').textContent=$('news-title').textContent;$('hud-evidence').textContent=s.clues.length+' / 8';$('hud-save').textContent=$('save-status').textContent.includes('unavailable')?'SESSION ONLY':'LOCAL SAVE ACTIVE';$('room-rail').innerHTML=roomIds.map((id,i)=>`<button data-quick-room="${id}" class="${s.place===id?'active':''}" aria-current="${s.place===id?'location':'false'}" title="${UI.locations[id].name} (${i+1})"><kbd>${i+1}</kbd><span>${UI.locations[id].name.replace('The ','')}</span><span class="rail-mark" aria-hidden="true"></span></button>`).join('');$('room-rail').querySelectorAll('[data-quick-room]').forEach(b=>b.onclick=()=>travel(b.dataset.quickRoom));if(lastPlace!==s.place&&field){lastPlace=s.place;$('slate-title').textContent=UI.locations[s.place].name;$('slate-meta').textContent=UI.locations[s.place].meta;$('scene-slate').classList.remove('show');void $('scene-slate').offsetWidth;$('scene-slate').classList.add('show');clearTimeout(slateTimer);slateTimer=setTimeout(()=>$('scene-slate').classList.remove('show'),2600);}if(!field)restoreHud();updateHeading();}
function updateHeading(){if(document.hidden)return;const walk=Cinema.getMode()==='walk';$('camera-mode-label').textContent=walk?'FIRST PERSON / LIVE':'CINEMATIC CAMERA';if(!walk){$('camera-bearing').textContent='LOCKED SHOT';return;}const deg=(Math.round(Cinema.heading()*180/Math.PI+90)%360+360)%360,dirs=['N','NE','E','SE','S','SW','W','NW'];$('camera-bearing').textContent=dirs[Math.round(deg/45)%8]+' '+String(deg).padStart(3,'0')+'°';}
function travel(place){restoreHud();UI.travel(place);update();}
function command(name){if(name!=='hud'&&name!=='back')restoreHud();if(name.startsWith('room:')){travel(name.slice(5));return;}if(['field','board','journal'].includes(name)){UI.view(name);return;}switch(name){case 'travel':showTravel();break;case 'people':showPeople();break;case 'briefing':showBriefing();break;case 'help':showHelp();break;case 'fullscreen':$('fullscreen').click();break;case 'sound':$('sound').click();break;case 'camera':if(UI.getState().ending)return;if(UI.getState().view!=='field')UI.view('field');Cinema.toggleMode();updateHeading();break;case 'hud':cleanFrame();break;case 'back':if(document.body.classList.contains('hud-hidden'))restoreHud();else if(UI.getState().view!=='field')UI.view('field');else showPause();break;}}
function panel(title,body,kicker,kind){UI.open(title,body,kicker);$('inspection').dataset.screen=kind;document.querySelectorAll('.game-dock [data-screen]').forEach(b=>b.classList.toggle('active',b.dataset.screen===kind));}
function showTravel(){const s=UI.getState();panel('Move through the directorate',`<p class="screen-intro">Travel directly to a room or jump to an inspection. Walking and travel do not advance the investigation clock.</p><div class="station-blueprint" aria-hidden="true"><div class="blueprint-cross"></div>${roomIds.map((id,i)=>`<span class="blueprint-room ${id===s.place?'current':''}"><b>${String(i+1).padStart(2,'0')}</b>${UI.locations[id].name.replace('The ','')}</span>`).join('')}<span class="blueprint-you">${svg('field')} YOUR POSITION: ${UI.locations[s.place].name.toUpperCase()}</span></div><div class="travel-grid">${roomIds.map((id,i)=>{const l=UI.locations[id],found=l.spots.filter(p=>p[5]&&s.clues.includes(p[5])).length,total=l.spots.filter(p=>p[5]).length;return `<article class="travel-card ${s.place===id?'current':''}"><div class="travel-card-top"><span class="eyebrow">${s.place===id?'CURRENT ROOM':'DIRECTORATE STATION'}</span><kbd>${i+1}</kbd></div><h3>${l.name}</h3><p>${l.meta}</p><div class="travel-progress"><span>${found} / ${total} findings</span><button data-travel="${id}" class="text-button" ${s.ending?'disabled':''}>Enter room</button></div><div class="quick-inspect">${l.spots.map(([target,label,x,y,clue])=>`<button data-quick-inspect="${target}" data-room="${id}" ${s.ending?'disabled':''}><span>${label}</span><span aria-hidden="true">${s.clues.includes(clue)?'✓':'+'}</span></button>`).join('')}</div></article>`;}).join('')}</div>`,'NAVIGATION / DIRECTORATE FLOOR PLAN','travel');document.querySelectorAll('[data-travel]').forEach(b=>b.onclick=()=>travel(b.dataset.travel));document.querySelectorAll('[data-quick-inspect]').forEach(b=>b.onclick=()=>UI.inspect(b.dataset.quickInspect,b.dataset.room));}
function showPeople(){panel('Persons of interest',`<p class="screen-intro">Question the team, establish their whereabouts, and confront a statement with the records you have recovered.</p><div class="people-screen">${['Vale','Imani','Kade'].map((name,i)=>`<button class="person dossier-person" data-open-person="${name}"><span class="portrait ${name}" role="img" aria-label="Portrait of ${name}"></span><span class="person-info"><small>PERSONNEL FILE / ${['CRISIS DIRECTOR','INTELLIGENCE ANALYST','PRESS LIAISON'][i]}</small><strong>${['Director Vale','Analyst Imani','Liaison Kade'][i]}</strong><span class="interview-label">Open interview</span></span></button>`).join('')}</div><p class="screen-note">Statements are leads. Physical records establish the chain.</p>`,'PERSONNEL / INTERVIEW DIRECTORY','people');document.querySelectorAll('[data-open-person]').forEach(b=>b.onclick=()=>UI.person(b.dataset.openPerson));}
function showBriefing(){const source=document.querySelector('.sidebar').innerHTML.replace(/id="([^"]+)"/g,'id="brief-$1"');panel('The Meridian Leak',`<div class="briefing-body">${source}</div>`,'CASE 007 / LIVE BRIEFING','briefing');$('brief-assessment').onclick=()=>UI.assessment();$('brief-hint').onclick=()=>UI.hint();$('brief-restart').onclick=()=>$('restart').click();}
const key=(k,label)=>`<li><kbd>${k}</kbd><span>${label}</span></li>`;
function showHelp(tab=helpTab){helpTab=tab;const controls=`<div class="help-columns"><section><h3>Switch views</h3><ul class="shortcut-list">${key('0','Return to the scene')}${key('B','Evidence board')}${key('J','Private notes')}${key('G','Location navigator')}${key('P','Interviews')}${key('I','Mission briefing')}${key('H / ?','This field manual')}</ul></section><section><h3>Control the frame</h3><ul class="shortcut-list">${key('1–4','Travel to a room')}${key('V','Cinematic / first-person view')}${key('F','Browser fullscreen')}${key('U','Hide / show the interface')}${key('M','Toggle ambient sound')}${key('Esc','Close a panel / return / pause')}</ul></section></div><section class="help-walk"><h3>First-person movement</h3><p><kbd>W A S D</kbd> Move <span>·</span> <kbd>← →</kbd> Turn <span>·</span> <kbd>E</kbd> Inspect</p><p>Drag the scene to look around. Click the scene to focus keyboard movement. Touch devices have on-screen movement controls. Reset position returns you to your current room’s starting point.</p></section><p class="screen-note">Shortcuts are inactive while you type or inspect a panel. Tab and Shift+Tab move through controls; Enter activates the focused button.</p>`;
const play=`<div class="manual-steps"><article><span>01</span><div><h3>Search and question</h3><p>Click illuminated points in the scene or approach a station in first-person view. Open Team to interview Vale, Imani, and Kade.</p></div></article><article><span>02</span><div><h3>Examine the records</h3><p>Compare document wording, scrub the camera timeline, and match the device and upload records. Correct findings are filed automatically.</p></div></article><article><span>03</span><div><h3>Build a case</h3><p>Open Evidence and select two cards to establish a direct connection. Follow the file, its export, physical presence, and its outbound path.</p></div></article><article><span>04</span><div><h3>Choose your assessment</h3><p>Open Briefing to file attribution and choose what to release. Your evidence and release decision determine the disposition. A closed case can be reopened.</p></div></article></div><div class="help-callout"><p>New discoveries advance the story clock. Travel, rechecking evidence, and hints are free. Progress and private notes save in this browser.</p><button id="help-hint" class="text-button">Request the next field hint</button></div>`;
const settings=`<div class="settings-list"><article><div><h3>Camera motion</h3><p>Parallax, particles, and transitions respect your reduced-motion preference.</p></div><button id="help-motion" class="icon-button">${$('motion').textContent}</button></article><article><div><h3>Ambient sound</h3><p>Optional rain, low ambient tones, and evidence notifications.</p></div><button id="help-sound" class="icon-button">${$('sound').textContent}</button></article><article><div><h3>Fullscreen</h3><p>The game fills the page by default. Browser fullscreen also removes browser chrome when supported.</p></div><button id="help-fullscreen" class="icon-button">${$('fullscreen').textContent}</button></article><article><div><h3>Clean frame</h3><p>Hide the interface for an uninterrupted scene. Press U or Escape to restore it.</p></div><button id="help-clean" class="icon-button">Hide interface</button></article></div><p class="screen-note">All controls remain available in both camera modes. View preferences do not change your case progress.</p>`;
panel('Field manual',`<p class="screen-intro">Your controls, navigation, and investigation guide.</p><nav class="help-tabs" aria-label="Manual sections">${[['controls','Controls & shortcuts'],['play','How to investigate'],['settings','Presentation']].map(([id,label])=>`<button data-help-tab="${id}" aria-pressed="${tab===id}" class="${tab===id?'active':''}">${label}</button>`).join('')}</nav><div class="help-content">${tab==='play'?play:tab==='settings'?settings:controls}</div>`,'BLACKLINE / FIELD MANUAL','help');document.querySelectorAll('[data-help-tab]').forEach(b=>b.onclick=()=>showHelp(b.dataset.helpTab));$('help-hint')?.addEventListener('click',()=>UI.hint());$('help-motion')?.addEventListener('click',()=>{$('motion').click();$('help-motion').textContent=$('motion').textContent;});$('help-sound')?.addEventListener('click',()=>{$('sound').click();$('help-sound').textContent=$('sound').textContent;});$('help-fullscreen')?.addEventListener('click',()=>{$('fullscreen').click();});$('help-clean')?.addEventListener('click',()=>{UI.close();cleanFrame();});}
function showPause(){panel('Investigation paused',`<p class="screen-intro">Your case is saved locally. Take a moment; the clock advances only with discoveries.</p><div class="pause-grid"><button id="resume-case" class="primary-button">Resume investigation</button><button data-pause="travel">Location navigator <kbd>G</kbd></button><button data-pause="briefing">Case briefing <kbd>I</kbd></button><button data-pause="help">Help & settings <kbd>H</kbd></button></div>`,'BLACKLINE / CASE MENU','pause');$('resume-case').onclick=()=>UI.close();document.querySelectorAll('[data-pause]').forEach(b=>b.onclick=()=>command(b.dataset.pause));}
document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>command(b.dataset.screen));$('clean-frame').onclick=cleanFrame;$('restore-hud').onclick=()=>{restoreHud();if(!Cinema.focus())document.querySelector('[data-view="field"]').focus();};
document.addEventListener('blackline:render',update);document.addEventListener('blackline:location',update);
$('inspection').addEventListener('close',()=>{delete $('inspection').dataset.screen;document.querySelectorAll('.game-dock [data-screen]').forEach(b=>b.classList.remove('active'));});
document.addEventListener('keydown',e=>{const el=e.target,typing=el?.isContentEditable||['INPUT','TEXTAREA','SELECT'].includes(el?.tagName);const action=NavigationShortcuts.action(e,{typing,modal:$('inspection').open,opening:!$('opening').hidden});if(action){e.preventDefault();command(action);}});
setInterval(updateHeading,220);update();
})();
